// Token Storage - Browser-compatible token storage implementation

import type { TokenStorage } from '../types';

export class BrowserTokenStorage implements TokenStorage {
  private storageKey: string;
  private useSessionStorage: boolean;

  constructor(storageKey: string = 'auth_token', useSessionStorage: boolean = false) {
    this.storageKey = storageKey;
    this.useSessionStorage = useSessionStorage;
  }

  private getStorage(): Storage {
    if (process.client) {
      return this.useSessionStorage ? sessionStorage : localStorage;
    }
    // Return a mock storage for SSR
    return {
      getItem: () => null,
      setItem: () => {},
      removeItem: () => {},
      clear: () => {},
      length: 0,
      key: () => null,
    };
  }

  getToken(): string | null {
    try {
      return this.getStorage().getItem(this.storageKey);
    } catch (error) {
      console.warn('Failed to get token from storage:', error);
      return null;
    }
  }

  setToken(token: string): void {
    try {
      this.getStorage().setItem(this.storageKey, token);
    } catch (error) {
      console.warn('Failed to save token to storage:', error);
    }
  }

  removeToken(): void {
    try {
      this.getStorage().removeItem(this.storageKey);
    } catch (error) {
      console.warn('Failed to remove token from storage:', error);
    }
  }
}

// Cookie-based token storage (more secure for SSR)
export class CookieTokenStorage implements TokenStorage {
  private cookieName: string;

  constructor(cookieName: string = 'auth_token') {
    this.cookieName = cookieName;
  }

  getToken(): string | null {
    const cookie = useCookie(this.cookieName, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
    });
    return cookie.value || null;
  }

  setToken(token: string): void {
    const cookie = useCookie(this.cookieName, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      maxAge: 60 * 60 * 24 * 7, // 7 days
    });
    cookie.value = token;
  }

  removeToken(): void {
    const cookie = useCookie(this.cookieName);
    cookie.value = null;
  }
}

// Chat types - Resource and request types for chats and messages

import type { BaseResource, UserResource, ImageResource, PaginationMeta } from './entities';
import { getImageUrl } from '~/utils/image';

// Chat type enum values (matching backend)
export const ChatType = {
  PRIVATE: 100,
  GROUP: 200,
  SUPPORT: 300,
} as const;

export type ChatTypeValue = (typeof ChatType)[keyof typeof ChatType];

// Message type enum values (matching backend)
export const MessageType = {
  TEXT: 100,
  MEDIA: 200,
  AUDIO: 300,
  SYSTEM: 400,
  LOCATION: 500,
} as const;

export type MessageTypeValue = (typeof MessageType)[keyof typeof MessageType];

// System message action values (matching backend `chat_message.system_action`)
export const SystemMessageAction = {
  USER_BLOCKED: 'user_blocked',
  USER_UNBLOCKED: 'user_unblocked',
  CONVERSATION_ABANDONED: 'conversation_abandoned',
  // The conversation was closed for safety (the other party was banned). Render the neutral
  // server-provided copy; never attribute it to a person or infer "banned" (ADR-219).
  USER_BANNED: 'user_banned',
} as const;

export type SystemMessageActionValue =
  (typeof SystemMessageAction)[keyof typeof SystemMessageAction];

// Participant role enum values
export const ParticipantRole = {
  OWNER: 100,
  PARTICIPANT: 200,
} as const;

export type ParticipantRoleValue = (typeof ParticipantRole)[keyof typeof ParticipantRole];

// Chat Participant Resource
export interface ChatParticipantResource {
  id: number;
  chat_id: string;
  participant_type: string;
  participant_id: number;
  participant?: UserResource | null;
  role: ParticipantRoleValue;
  last_seen_message_id?: number | null;
  is_active: boolean;
  unread_count: number;
  joined_at: string;
  left_at?: string | null;
  created_at: string;
  updated_at: string;
}

// Moderation status enum values (matching backend `chat_message.moderation.status`)
export const ModerationStatus = {
  CLEAN: 'clean',
  MASKED: 'masked',
} as const;

export type ModerationStatusValue = (typeof ModerationStatus)[keyof typeof ModerationStatus];

// Per-viewer moderation envelope (ADR-216 reversible chat link/contact masking).
// Always present on a message. `status` plain string to tolerate unknown future values.
export interface MessageModeration {
  status: ModerationStatusValue | string;
  can_reveal: boolean;
  reason?: string | null;
}

// Chat Message Resource
export interface ChatMessageResource {
  id: number;
  chat_id: string;
  participant_type: string;
  participant_id: number;
  participant?: UserResource | null;
  type: MessageTypeValue;
  content?: string | null;
  // Set on SYSTEM (type=400) messages; plain string to tolerate unknown future actions
  system_action?: string | null;
  // Per-viewer masking envelope (ADR-216). Masked content is delivered already masked by the
  // server; the original is revealable on demand via the reveal endpoint.
  moderation?: MessageModeration | null;
  media_path?: string | null;
  media_type?: string | null;
  media_size?: number | null;
  parent_id?: number | null;
  replies_count: number;
  is_reply: boolean;
  is_text: boolean;
  is_media: boolean;
  is_audio: boolean;
  is_location?: boolean;
  media_duration?: number | null;
  parent?: ChatMessageResource | null;
  reactions_count?: Array<{ reaction: string; count: number }>;
  created_at: string;
  updated_at: string;
  deleted_at?: string | null;
}

// Chat Resource
export interface ChatResource {
  id: string; // UUID
  type: ChatTypeValue;
  name?: string | null;
  settings: Record<string, unknown>;
  last_message_id?: number | null;
  last_message_at?: string | null;
  last_message?: ChatMessageResource | null;
  participants?: ChatParticipantResource[];
  unread_count?: number; // caller-scoped; may be absent on older payloads
  is_read?: boolean; // caller-scoped; true ⇔ unread_count === 0
  created_at: string;
  updated_at: string;
}

// Request types

export interface CreateChatRequest {
  type: ChatTypeValue;
  participant_ids: number[];
  name?: string; // For group chats
  owner_id?: number; // For group chats
}

export interface SendMessageRequest {
  chat_id: string;
  type: MessageTypeValue;
  content?: string;
  parent_id?: number; // For replies
  media?: File; // For media/audio messages
  media_duration?: number; // Duration in seconds for audio/video
}

// Location message content (JSON-encoded in message.content)
export interface LocationContent {
  latitude: number;
  longitude: number;
  location_name: string;
  notes?: string;
}

// Parse location content from JSON string
export function parseLocationContent(content: string): LocationContent | null {
  try {
    const parsed = JSON.parse(content);
    if (typeof parsed.latitude === 'number' && typeof parsed.longitude === 'number') {
      return parsed as LocationContent;
    }
    return null;
  } catch {
    return null;
  }
}

// Convert lat/lng to OSM tile coordinates
function latLngToTile(lat: number, lng: number, zoom: number): { x: number; y: number } {
  const n = Math.pow(2, zoom);
  const x = Math.floor(((lng + 180) / 360) * n);
  const clampedLat = Math.max(-85.05, Math.min(85.05, lat));
  const latRad = (clampedLat * Math.PI) / 180;
  const y = Math.floor(((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2) * n);
  return { x, y };
}

// Build map tile URL for a location message using OSM tile server
export function buildLocationMapUrl(loc: LocationContent): string {
  const zoom = 15;
  const { x, y } = latLngToTile(loc.latitude, loc.longitude, zoom);
  return `https://tile.openstreetmap.org/${zoom}/${x}/${y}.png`;
}

export interface UpdateMessageRequest {
  content: string;
}

// Pagination meta with unread count
export interface ChatPaginationMeta extends PaginationMeta {
  unread_count?: number;
}

// vue-advanced-chat compatible types

export interface VacUser {
  _id: string;
  username: string;
  avatar?: string;
  status?: {
    state: 'online' | 'offline';
    lastChanged?: string;
  };
}

export interface VacMessage {
  _id: string;
  indexId?: string;
  content: string;
  senderId: string;
  username?: string;
  avatar?: string;
  date: string;
  timestamp: string;
  system?: boolean;
  saved?: boolean;
  distributed?: boolean;
  seen?: boolean;
  deleted?: boolean;
  failure?: boolean;
  disableActions?: boolean;
  disableReactions?: boolean;
  // Per-viewer masking envelope carried through for the reveal affordance (ADR-216). The UI guards
  // the reveal action on `moderation.can_reveal` so it never blind-enumerates the reveal endpoint.
  moderation?: MessageModeration | null;
  files?: VacFile[];
  reactions?: Record<string, string[]>;
  replyMessage?: {
    _id: string;
    content: string;
    senderId: string;
    files?: VacFile[];
  } | null;
}

export interface VacFile {
  name: string;
  type: string; // REQUIRED by vue-advanced-chat
  extension: string; // REQUIRED by vue-advanced-chat
  url: string;
  localUrl?: string;
  preview?: string;
  size?: number;
  audio?: boolean;
  duration?: number;
  progress?: number;
  loading?: boolean; // Controls blur overlay - set to false when media is loaded
  blob?: Blob;
}

export interface VacRoom {
  roomId: string;
  roomName: string;
  avatar?: string;
  unreadCount?: number;
  index?: string | number;
  lastMessage?: {
    _id: string;
    content: string;
    senderId: string;
    username?: string;
    timestamp: string;
    saved?: boolean;
    distributed?: boolean;
    seen?: boolean;
    new?: boolean;
  };
  users: VacUser[];
  typingUsers?: string[];
}

// Helper to extract file extension from path or MIME type
function extractExtension(mediaPath?: string | null, mediaType?: string | null): string {
  if (mediaPath) {
    const fileName = mediaPath.split('/').pop() || '';
    if (fileName.includes('.')) {
      return fileName.split('.').pop()?.toLowerCase() || '';
    }
  }
  if (mediaType) {
    return mediaType.split('/').pop() || '';
  }
  return '';
}

// Convert backend reactions_count to vue-advanced-chat reactions format
// VAC expects: { "emoji": ["userId1", "userId2"] }
// Backend provides: [{ reaction: "emoji", count: N }]
export function buildVacReactions(
  counts: Array<{ reaction: string; count: number }> | undefined,
): Record<string, string[]> | undefined {
  if (!counts?.length) return undefined;
  const result: Record<string, string[]> = {};
  for (const { reaction, count } of counts) {
    if (count <= 0) continue;
    const userIds: string[] = [];
    // Fill with placeholder IDs (VAC needs user IDs array for count display)
    for (let i = 0; i < count; i++) {
      userIds.push(`user-${reaction}-${i}`);
    }
    result[reaction] = userIds;
  }
  return Object.keys(result).length > 0 ? result : undefined;
}

// Helper functions for transforming API responses to vue-advanced-chat format

export function chatToVacRoom(
  chat: ChatResource,
  currentUserId: number,
  locale: string = 'en',
): VacRoom {
  // For private chats, get the other participant
  const otherParticipant = chat.participants?.find((p) => p.participant_id !== currentUserId);
  const isPrivate = chat.type === ChatType.PRIVATE;

  const roomName = isPrivate
    ? (otherParticipant?.participant?.name ?? 'Unknown')
    : (chat.name ?? 'Group Chat');

  const avatar = isPrivate
    ? getImageUrl(otherParticipant?.participant?.avatar, 'thumbnail')
    : undefined;

  const users: VacUser[] = (chat.participants ?? []).map((p) => ({
    _id: String(p.participant_id),
    username: p.participant?.name ?? 'Unknown',
    avatar: getImageUrl(p.participant?.avatar, 'thumbnail'),
    status: {
      state: 'offline' as const,
    },
  }));

  const currentParticipant = chat.participants?.find((p) => p.participant_id === currentUserId);

  return {
    roomId: chat.id,
    roomName,
    avatar,
    unreadCount: chat.unread_count ?? currentParticipant?.unread_count ?? 0,
    index: chat.last_message_at ?? chat.created_at,
    lastMessage: chat.last_message
      ? {
          _id: String(chat.last_message.id),
          content: chat.last_message.deleted_at
            ? 'This message was deleted'
            : (chat.last_message.content ?? ''),
          senderId: String(chat.last_message.participant_id),
          username: chat.last_message.participant?.name,
          timestamp: formatTimestamp(chat.last_message.created_at, locale),
          saved: true,
          distributed: true,
          seen: true,
        }
      : undefined,
    users,
  };
}

/**
 * Whether a message carries loadable media: a MEDIA/AUDIO message with a stored path.
 * Shared guard reused by the media loaders and the VacFile builder so the type/path
 * predicate cannot drift across its call sites.
 */
export function isLoadableMediaMessage(
  m: Pick<ChatMessageResource, 'type' | 'media_path'>,
): boolean {
  return (m.type === MessageType.MEDIA || m.type === MessageType.AUDIO) && !!m.media_path;
}

/**
 * Build the vue-advanced-chat file descriptor for a media/audio message once its
 * authenticated blob URL is available. Pure — the caller owns the loadable guard
 * (`isLoadableMediaMessage`) and any reactive update. Audio (type 300) forces an
 * `audio/mpeg` MIME regardless of the stored media_type (backend may store video/mp4).
 * Do NOT set `progress`/`preview` — they trigger the blur overlay in vue-advanced-chat.
 */
export function buildVacFileFromMessage(message: ChatMessageResource, blobUrl: string): VacFile {
  const fileName = message.media_path?.split('/').pop() || 'media';
  const extension = extractExtension(message.media_path, message.media_type);
  const isAudio = message.type === MessageType.AUDIO;
  const fileType = isAudio ? 'audio/mpeg' : message.media_type || 'application/octet-stream';

  const file: VacFile = {
    name: fileName,
    type: fileType, // REQUIRED by vue-advanced-chat
    extension, // REQUIRED by vue-advanced-chat
    url: blobUrl,
    loading: false, // Clears blur overlay - tells vue-advanced-chat media is loaded
  };

  if (message.media_size) {
    file.size = message.media_size;
  }
  if (message.media_duration) {
    file.duration = message.media_duration;
  }
  if (isAudio) {
    file.audio = true;
  }

  return file;
}

/**
 * "Is there another page" check shared by the rooms and messages pagers.
 *
 * `loadedCount` is how many rows we have ACTUALLY received so far, not `(page - 1) * perPage`.
 * That arithmetic assumed the server honours the page size we asked for, and it did not: the chat
 * endpoints ignored `per_page` entirely and answered every request with 15 rows. A 50-per-page
 * client therefore credited itself 50 rows per page it had never received, overshot the total, and
 * stopped early — silently truncating any conversation past ~45 messages. Counting real rows
 * cannot drift from the server that way, whatever page size it decides to return.
 *
 * An empty page always ends paging regardless of `total`: the free-tier history window shrinks over
 * time, so a total captured on page 1 can outlive the rows behind it.
 *
 * `total` must already be defaulted (meta.total || 0).
 */
export function computeHasMore({
  perPage,
  receivedCount,
  loadedCount,
  total,
}: {
  perPage: number;
  receivedCount: number;
  loadedCount: number;
  total: number;
}): boolean {
  if (receivedCount === 0) {
    return false;
  }
  if (total > 0) {
    return loadedCount < total;
  }
  return receivedCount >= perPage;
}

/**
 * Highest message id in a loaded list, or undefined when empty — the read-cursor for
 * mark-read, so we never advance past a message the user hasn't seen. The length guard
 * avoids `Math.max()` returning -Infinity on an empty list.
 */
export function deriveLatestMessageId(
  messages: Pick<ChatMessageResource, 'id'>[],
): number | undefined {
  return messages.length ? Math.max(...messages.map((m) => m.id)) : undefined;
}

export function messageToVacMessage(
  message: ChatMessageResource,
  locale: string = 'en',
  apiBaseUrl: string = '',
  currentUserId: number = 0,
  mediaResolver?: MediaUrlResolver,
  revealResolver?: RevealResolver,
): VacMessage {
  const isDeleted = !!message.deleted_at;

  // SYSTEM messages (type=400, e.g. "Jane left the conversation.") render as a centered
  // system notice. Content is already server-localized; do not re-translate. Unknown future
  // system_action values still surface the server content gracefully.
  if (message.type === MessageType.SYSTEM) {
    return {
      _id: String(message.id),
      indexId: message.created_at,
      content: message.content ?? '',
      senderId: String(message.participant_id),
      date: formatDate(message.created_at, locale),
      timestamp: formatTimestamp(message.created_at, locale),
      system: true,
      disableActions: true,
      disableReactions: true,
    };
  }

  // Build files array for media messages
  // Only include files when we have a blob URL (authenticated), otherwise skip
  // This prevents the loading spinner from appearing with placeholder URLs
  let files: VacFile[] | undefined;
  if (isLoadableMediaMessage(message)) {
    // Get blob URL if available (authenticated media). Without it the message renders
    // without media until the blob loads, avoiding a placeholder-URL loading spinner.
    const blobUrl = mediaResolver?.getBlobUrl(message.chat_id, message.id);
    if (blobUrl) {
      files = [buildVacFileFromMessage(message, blobUrl)];
    }
  }

  // Build reply message from parent (1 level deep, parent.parent is always null)
  let replyMessage: VacMessage['replyMessage'] = null;
  if (message.parent && !isDeleted) {
    const parentDeleted = !!message.parent.deleted_at;

    // Build readable content for reply preview based on parent type
    let parentContent = message.parent.content ?? '';
    if (parentDeleted) {
      parentContent = 'This message was deleted';
    } else if (message.parent.type === MessageType.AUDIO) {
      parentContent = '🎵 Audio message';
    } else if (message.parent.type === MessageType.LOCATION) {
      const loc = parseLocationContent(message.parent.content ?? '');
      parentContent = loc?.location_name ? `📍 ${loc.location_name}` : '📍 Location';
    }

    replyMessage = {
      _id: String(message.parent.id),
      content: parentContent,
      senderId: String(message.parent.participant_id),
    };

    // Include media preview in reply if parent had media
    if (
      (message.parent.type === MessageType.MEDIA || message.parent.type === MessageType.AUDIO) &&
      message.parent.media_path
    ) {
      const parentBlobUrl = mediaResolver?.getBlobUrl(message.parent.chat_id, message.parent.id);
      if (parentBlobUrl) {
        replyMessage.files = [
          {
            name: message.parent.media_path.split('/').pop() || 'media',
            type: message.parent.media_type || 'application/octet-stream',
            extension: extractExtension(message.parent.media_path, message.parent.media_type),
            url: parentBlobUrl,
          },
        ];
      }
    }
  }

  // Handle location message content — formatted text only, map image loaded async.
  // Masking (ADR-216): `message.content` arrives already masked for the recipient. If the viewer
  // revealed the original this session, the injected revealResolver returns it; otherwise we render
  // the masked content verbatim (never re-detect/re-mask client-side).
  let content = isDeleted
    ? 'This message was deleted'
    : (revealResolver?.getRevealed(message.id) ?? message.content ?? '');
  if (!isDeleted && message.type === MessageType.LOCATION) {
    const loc = parseLocationContent(message.content ?? '');
    if (loc) {
      content = loc.location_name || 'Shared location';
      if (loc.notes) {
        content += `\n${loc.notes}`;
      }

      // Map tile as image file (OSM tile server — same as interactive map page)
      // Coordinates encoded in name for click-to-open-maps handler
      files = [
        {
          name: `location:${loc.latitude},${loc.longitude}`,
          type: 'image/png',
          extension: 'png',
          url: buildLocationMapUrl(loc),
          loading: false,
        },
      ];
    }
  }

  // Build reactions in vue-advanced-chat format
  const reactions = buildVacReactions(message.reactions_count);

  return {
    _id: String(message.id),
    indexId: message.created_at, // Keep original timestamp for edit check
    content,
    senderId: String(message.participant_id),
    username: message.participant?.name,
    avatar: getImageUrl(message.participant?.avatar, 'thumbnail'),
    date: formatDate(message.created_at, locale),
    timestamp: formatTimestamp(message.created_at, locale),
    deleted: isDeleted,
    // Only disable actions for deleted messages - onlyMe handles showing edit/delete for own messages
    disableActions: isDeleted,
    disableReactions: isDeleted,
    moderation: message.moderation ?? null,
    files,
    reactions,
    replyMessage,
    saved: true,
    distributed: true,
    seen: true,
  };
}

// Helper to format date for display (locale-aware)
export function formatDate(dateString: string, locale: string = 'en'): string {
  const date = new Date(dateString);
  const localeCode = locale === 'es' ? 'es-ES' : 'en-US';
  return date.toLocaleDateString(localeCode, {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });
}

// Helper to format timestamp for display (locale-aware)
export function formatTimestamp(dateString: string, locale: string = 'en'): string {
  const date = new Date(dateString);
  const localeCode = locale === 'es' ? 'es-ES' : 'en-US';
  return date.toLocaleTimeString(localeCode, {
    hour: 'numeric',
    minute: '2-digit',
    hour12: locale !== 'es', // 24h format for Spanish
  });
}

// Media URL resolver interface for authenticated media loading
export interface MediaUrlResolver {
  getBlobUrl: (chatId: string, messageId: number) => string | null;
  getPlaceholder: (mediaType: string) => string;
}

// Reveal overlay resolver (ADR-216). Mirrors MediaUrlResolver: the pure transform reads the original
// revealed content (if the viewer revealed it this session) from this injected resolver. Returning
// null means "not revealed" → the transform renders the masked content. The resolver owns no state;
// the per-session reveal cache lives in a per-request useState owned by the composable layer.
export interface RevealResolver {
  getRevealed: (messageId: number) => string | null;
}

// Helper to check if message is editable (within 15 minutes and own message)
export function isMessageEditable(
  createdAt: string,
  currentUserId: number,
  senderId: number,
): boolean {
  if (senderId !== currentUserId) return false;
  const created = new Date(createdAt);
  const now = new Date();
  const diffMs = now.getTime() - created.getTime();
  const diffMin = diffMs / (1000 * 60);
  return diffMin <= 15;
}

// Helper to build media URL using the API endpoint
export function buildMediaUrl(chatId: string, messageId: number, apiBaseUrl: string): string {
  return `${apiBaseUrl}/api/v1/chats/${chatId}/messages/${messageId}/media`;
}

// Derive a proper upload File for a recorded audio blob. vue-advanced-chat hands the recorder
// output back as a raw blob named "blob" with no extension; give it a `recording.<ext>` name +
// a sane MIME type so the backend stores it correctly (webm→webm, mp4→m4a, anything else→ogg).
// Files that already carry a real name pass straight through. Caller guards on isAudio; this
// function assumes the blob is audio. Pure: depends only on the input File's name/type.
export function deriveAudioUploadFile(file: File): File {
  if (file.name && file.name !== 'blob') return file;
  const ext = file.type.includes('webm') ? 'webm' : file.type.includes('mp4') ? 'm4a' : 'ogg';
  return new File([file], `recording.${ext}`, { type: file.type || 'audio/webm' });
}

