import type { FeedDomain, FeedItemResource } from '~/api/types'
import type { FilterCondition } from '~/api/types'
import { filter } from '~/api/types'

interface UseInfiniteFeedOptions {
  domains?: Ref<FeedDomain[]>
  typeFilter?: Ref<number[]>
  search?: Ref<string>
  seoCitySlug?: Ref<string | undefined>
  categoryId?: Ref<number | undefined>
}

export function useInfiniteFeed(options: UseInfiniteFeedOptions = {}) {
  const { domains, typeFilter, search, seoCitySlug, categoryId } = options
  const { feedService } = useApi()
  const { getLocation } = useLocationStorage()

  const isMounted = ref(false)
  onMounted(() => { isMounted.value = true })

  // SSR-safe: same guard as useInfinitePosts
  const position = computed((): string | undefined => {
    if (!isMounted.value) return undefined
    try {
      const location = getLocation()
      return location?.id ? String(location.id) : undefined
    } catch {
      return undefined
    }
  })

  // Encode feed-specific params as FilterCondition[] for identifier tracking only.
  // useInfiniteList resets pagination whenever this computed changes value.
  const filters = computed<FilterCondition[]>(() => {
    const result: FilterCondition[] = []
    if (domains?.value?.length) result.push(filter('domains', 'in', domains.value))
    if (typeFilter?.value?.length) result.push(filter('type', 'in', typeFilter.value))
    if (seoCitySlug?.value) result.push(filter('seo_city', '=', seoCitySlug.value))
    if (categoryId?.value) result.push(filter('category_id', '=', categoryId.value))
    return result
  })

  const orders = ref([])

  return useInfiniteList<FeedItemResource>(
    (params) => feedService.list({
      domains: domains?.value?.length ? domains.value : undefined,
      type: typeFilter?.value?.length ? typeFilter.value : undefined,
      search: params.search,
      position: params.position,
      seo_city: seoCitySlug?.value,
      category_id: categoryId?.value,
      page: params.page,
      per_page: params.per_page,
    }),
    filters,
    orders,
    { position, search }
  )
}
